CREATE VIEW "TEST_AP"."ixvITL_LastWhs" ( "ItemCode", "SysNumber", "WhsCode" ) AS SELECT		T0."ItemCode", lastLogEntry."SysNumber", T0."LocCode" AS "WhsCode" FROM		"TEST_AP".OITL  T0 INNER JOIN	(SELECT	MAX("LogEntry") AS "LogEntry", "ItemCode", "SysNumber" FROM "TEST_AP".ITL1 GROUP BY "ItemCode", "SysNumber") AS lastLogEntry ON lastLogEntry."LogEntry" = T0."LogEntry" AND T0."ItemCode" = lastLogEntry."ItemCode" WITH READ ONLY